(()=>{
 const checkList=document.querySelector('#feed-check-list');const request=document.querySelector('#manual-request'),submit=document.querySelector('#manual-submit'),status=document.querySelector('#manual-status'),list=document.querySelector('#manual-list'),download=document.querySelector('#manual-download'),review=document.querySelector('#review-manual-list'),output=document.querySelector('#manual-output');let lastError='';const reviewOpen=new Set();
 const element=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
 async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw Error(data.error||'Could not update the changes.');return data}
 function detail(change){const box=element('div',undefined,'feed-edit-detail');const title=change.field==='route_color'?'Route color change':change.field==='route_short_name'?'Route short-name change':'Route field change';box.append(element('strong',title,'feed-edit-type'));
  const route=element('p',undefined,'feed-edit-route');route.append(document.createTextNode('Route '));const name=change.route_short_name||change.route_id;const nameNode=element('code',name);route.append(nameNode);if(change.route_long_name)route.append(document.createTextNode(' · '+change.route_long_name));route.append(document.createTextNode(' · ID '));route.append(element('code',change.route_id));if(change.agency_id){route.append(document.createTextNode(' · Agency '));route.append(element('code',change.agency_id))}box.append(route);
  const line=element('p',undefined,'feed-edit-change');line.append(element('span','routes.txt','gtfs-file'),document.createTextNode(' · '),element('code',change.field),document.createTextNode(': '),element('code',change.before||'(empty)'),document.createTextNode(' → '),element('code',change.after));box.append(line);return box}
 function appendChanges(parent,changes){if(!changes.length)return;if(changes.length<=12){changes.forEach(c=>parent.append(detail(c)));return}const group=element('details',undefined,'feed-edit-detail'),heading=element('summary',changes.length+' route changes');group.append(heading);changes.forEach(c=>group.append(detail(c)));parent.append(group)}
 function render(data){list.replaceChildren();review.replaceChildren();output.replaceChildren();checkList.replaceChildren();if(data.items.some(i=>i.active)){checkList.append(element('h3','Feed edit checks'));}download.hidden=true;if(data.version){output.append(element('h3','Applied feed edits'));data.items.filter(i=>i.applied).forEach(i=>{const row=element('div');row.append(element('strong',i.id+' · '+i.text));(i.changes||[]).forEach(c=>row.append(element('p',`routes.txt · Route ${c.route_id} · ${c.field}: ${c.before||'(empty)'} → ${c.after}`,'helper')));output.append(row)})}status.textContent=lastError||(data.items.length?`${data.items.filter(i=>i.active).length} selected for review.`:'No feed edits yet.');
  if(data.items.some(i=>i.active||i.applied))review.append(element('h3','Feed edits'));
  [...data.items].reverse().forEach(item=>{const state=item.reflection==='reflected'?'✓ Reflected in GTFS':item.reflection==='not_reflected'?'❗ Not reflected in GTFS':'? Cannot determine from GTFS';const card=element('article',undefined,'feed-edit-card');const top=element('div',undefined,'feed-edit-heading');const left=element('div');left.append(element('strong',item.id,'feed-edit-id'),element('span',state,'feed-edit-state'));const button=element('button',item.active?'Remove task':'Restore task','btn');button.type='button';button.onclick=async()=>{button.disabled=true;try{lastError='';render(await api('/api/manual-edits/toggle',{id:item.id,active:!item.active}))}catch(e){lastError=e.message;status.textContent=lastError;button.disabled=false}};top.append(left,button);card.append(top,element('p',item.text,'feed-edit-request'));appendChanges(card,item.proposed_changes||[]);(item.assumptions||[]).forEach(a=>card.append(element('p','Assumption: '+a,'feed-edit-assumption')));if(item.active){list.append(card);const check=element('div',undefined,'feed-edit-check');check.append(element('strong',item.id,'feed-edit-id'),document.createTextNode(' · '+item.text+' · '+state));checkList.append(check)}
   if(item.active||item.applied){const row=element('details',undefined,'change-ticket');row.open=reviewOpen.has(item.id);row.addEventListener('toggle',()=>{if(row.open)reviewOpen.add(item.id);else reviewOpen.delete(item.id)});const header=element('summary'),id=element('span',item.id,'ticket-id'),badge=element('span',state,'ticket-status needs_modeling'),title=element('strong',item.text,'ticket-title');header.append(id,badge,title);row.append(header);const section=element('div',undefined,'ticket-section');section.append(element('h3','Feed edit'),element('p','Reflected in the loaded GTFS? '+state,'helper'));if(item.active){appendChanges(section,item.proposed_changes||[]);(item.assumptions||[]).forEach(a=>section.append(element('p','Assumption: '+a,'feed-edit-assumption')))}else{section.append(element('p','The next run will rebuild the output without this edit.','helper'))}row.append(section);review.append(row)}
  })}
 async function refresh(){try{const data=await api('/api/manual-edits');if(window.gtfsHostedRequest)lastError='';render(data)}catch(e){lastError=e.message;status.textContent=lastError}}
 submit.onclick=async()=>{let text=request.value.trim();if(!text){status.textContent='Describe the change first.';return}lastError='';submit.disabled=true;status.textContent='Interpreting the requested change…';try{const data=await api('/api/manual-edits',{text});request.value='';render(data);status.textContent='Change added for review. Check the interpretation below.'}catch(e){lastError=e.message;status.textContent=lastError}finally{submit.disabled=false}};
 document.querySelector('#import-feed').addEventListener('click',()=>setTimeout(refresh,3000));document.querySelector('#upload-feed').addEventListener('click',()=>setTimeout(refresh,3000));refresh();window.addEventListener('pipeline-updated',refresh);if(!window.gtfsHostedRequest)setInterval(refresh,5000);
})();
